  if (!existsSync(n)) throw new Error(`missing required file: ${n}`);
}

function readNum(name) {
  const raw = readFileSync(name, "utf8").trim();
  if (raw === "") throw new Error(`empty file: ${name}`);
  const v = Number(raw);
  if (!Number.isFinite(v)) throw new Error(`non-numeric value in ${name}: ${JSON.stringify(raw)}`);
  return v;
}

const seed = readNum("seed.txt");
const stage1 = readNum("stage1.txt");
const stage2 = readNum("stage2.txt");
const stage3 = readNum("stage3.txt");

const checks = [
  ["stage1 = seed + 2", stage1, seed + 2],
  ["stage2 = stage1 ^ 2", stage2, stage1 ** 2],
  ["stage3 = stage2 - 4", stage3, stage2 - 4],
];

let failed = false;
for (const [label, actual, expected] of checks) {
  const ok = Object.is(actual, expected);
  if (!ok) failed = true;
  console.log(`${ok ? "PASS" : "FAIL"} ${label}: actual=${actual} expected=${expected}`);
}

console.log(`values seed=${seed} stage1=${stage1} stage2=${stage2} stage3=${stage3}`);
if (failed) { console.error("VERIFICATION FAILED"); process.exit(1); }
console.log("ALL STAGE CHECKS PASSED");
'

